sys_script_include.script:
var ContrastAppListIntegrationJson = Class.create();
ContrastAppListIntegrationJson.prototype = Object.extendsObject(sn_vul.ApplicationVulnerabilityIntegrationBase, {

    UTIL: new x_ntsi_contrast_ap.ContrastUtilBase(),

    retrieveData: function() {

        var resp = new x_ntsi_contrast_ap.ContrastUtilBase().triggerAPI(this.IMPLEMENTATION);
        var responseBody = resp.getBody();

        if (resp.getStatusCode() == 200) {
            var orgID = new x_ntsi_contrast_ap.ContrastUtilBase().getApiORGDetails();
            var appURL = new x_ntsi_contrast_ap.ContrastUtilBase().getApiURLDetails();
            try {

                var apps = JSON.parse(responseBody);
                var application_parms = apps.applications;
                var arr = [];

                for (var a in application_parms) {

                    var vulresp = new x_ntsi_contrast_ap.ContrastUtilBase().getIASTVulnerabilities(this.IMPLEMENTATION, application_parms[a].app_id);

                    if (vulresp.getStatusCode() == 200) {
                        var vul = JSON.parse(vulresp.getBody());
                        var trace = vul.traces;
                        for (var a1 in trace) {
                            var obj = trace[a1];

                            obj.app_id = application_parms[a].app_id;
                            obj.app_name = application_parms[a].name;
                            obj.app_version = trace[a1].app_version_tags.toString();
                            obj.organization_id = orgID;
                            //Generate Source link and Vul link
                            obj.source_link = "https://" + appURL + "/Contrast/static/ng/index.html#/" + orgID + "/applications/" + application_parms[a].app_id + "/vulns/" + trace[a1].uuid;
                            obj.vul_link = "https://" + appURL + "/Contrast/api/ng/" + orgID + "/orgtraces/mark";
                            arr.push(obj);

                            //Generate object for Application 
                            var appObj = {
                                source_app_id: application_parms[a].app_id + "",
                                app_name: application_parms[a].name + "",
                                description: application_parms[a].name + "",
                                source_app_guid: obj.uuid + "",
                            };

                            var result = this.AVR_API.createOrUpdateApp(appObj);

                        }
                    }
                }
                arr.join();
                var objtraces = {
                    "traces": arr
                };


                //Generate Attachment with Response payload to trigger data source

                var attachmentGr = new GlideSysAttachment();
                var fileName = this.integrationGr.name + "_" + new GlideDateTime().toString() + ".json";
                var sysId = attachmentGr.write(this.integrationProcessGr, fileName, "json", JSON.stringify(objtraces));
                var obj1 = {
                    contents: sysId,
                    contentType: "sys_attachment",
                    extension: "json"
                };

                return obj1;

            } catch (e) {
                gs.error("Failed to parse JSON: " + e.message);
                // Optionally handle the error or take fallback action
            }

        } else {
            gs.error("API Failed with status code: " + resp.getStatusCode());
            return null;
        }
    },

    shouldRetry: function(process) {
        return true;
    },





    type: 'ContrastAppListIntegrationJson'
});
